import { subject, columns, where, orderBy, val } from '../xl/ttl.js'
import { Query } from '../query.js'

export class SELECT extends Query { SELECT = {}
  static from (...args) { return (new this).from (...args) }
  static columns (...args) { return (new this).columns (...args) }
  static get localized() { return (new this)._set('localized', true) }
  static get distinct() { return (new this)._set('distinct', true) }
  static get one()     { return (new this)._set('one', true) }
  get localized()   { return this._set('localized', true) }
  get distinct()    { return this._set('distinct', true) }
  columns (...args) { return this._add('columns', columns (...args)) }
  from    (...args) { return this._set('from', subject (...args)) }
  where   (...args) { return this._add('where', where (...args)) }
  having  (...args) { return this._add('having', where (...args)) }
  groupBy (...args) { return this._add('groupBy', columns (...args)) }
  orderBy (...args) { return this._add('orderBy', orderBy (...args)) }
  limit   (...args) { return args[0]?.raw ? this.top(...args) : this.top(args[0]).skip(args[1]) }
  top     (...args) { if (args[0]) (this._.limit ??= {}).rows = val(...args); return this }
  skip    (...args) { if (args[0]) (this._.limit ??= {}).offset = val(...args); return this }
  offset  (...args) { return this.skip(...args) }
}
